<?php require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/auth.php';require_request_access();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$code='MR-'.date('Ymd').'-'.random_int(100,999);$s=$pdo->prepare('INSERT INTO maintenance_requests(request_code,equipment_id,reported_by,problem_description,priority,status) VALUES(?,?,?,?,?,"Pending")');$s->execute([$code,(int)$_POST['equipment_id'],$_SESSION['user']['id'],trim($_POST['problem_description']),$_POST['priority']]);flash('Maintenance request submitted.');header('Location:requests.php');exit;}$equipment=$pdo->query("SELECT id,equipment_code,equipment_name FROM equipment WHERE status != 'Retired' ORDER BY equipment_name")->fetchAll(PDO::FETCH_ASSOC);$page_title='New Request';require __DIR__.'/../includes/header.php';?><h1 class="page-heading mb-4">Submit Maintenance Request</h1><div class="panel"><form method="post" class="row g-3"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><div class="col-md-7"><label class="form-label">Equipment</label><select class="form-select" name="equipment_id" required><?php foreach($equipment as $e):?><option value="<?=$e['id']?>"><?=e($e['equipment_code'].' — '.$e['equipment_name'])?></option><?php endforeach?></select></div><div class="col-md-5"><label class="form-label">Priority</label><select class="form-select" name="priority"><?php foreach(['Low','Medium','High','Critical'] as $x):?><option><?=$x?></option><?php endforeach?></select></div><div class="col-12"><label class="form-label">Problem Description</label><textarea class="form-control" name="problem_description" rows="5" required placeholder="Describe the issue, symptoms, and safety impact."></textarea></div><div><button class="btn btn-primary">Submit Request</button><a href="requests.php" class="btn btn-light">Cancel</a></div></form></div><?php require __DIR__.'/../includes/footer.php'; ?>
